//! Embeds the Windows resources — hydra.ico and a VERSIONINFO block — into
//! hydra-gui.exe. Explorer, the taskbar, and Task Manager's "Startup apps"
//! page all read these, so without them the exe gets a generic icon and the
//! login item shows an anonymous name instead of "Hydra Download Manager".
//!
//! The .rc is generated by the shared helper and compiled by embed-resource:
//! rc.exe on a Windows host, llvm-rc when cross-compiling with cargo-xwin
//! (scripts/build-windows-installer.sh already puts Homebrew LLVM on PATH).

#[path = "../../scripts/windows/version_resource.rs"]
mod version_resource;

fn main() {
    version_resource::embed(&version_resource::Resource {
        description: "Hydra Download Manager",
        original_filename: "hydra-gui.exe",
        internal_name: "hydra-gui",
        icon: true,
        library: false,
    });
}
